const escapeHtml=v=>String(v??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
function sectionInfo(category){const custom=window.NUZHA_SERVER_CONTENT?.settings?.menuSections?.[category]||{},base=sectionDefaults[category]||{};const pick=k=>String(custom[k]||"").trim()||base[k]||"";return {image:pick("image"),tagline:lang==="ar"?pick("taglineAr"):pick("taglineEn")}}
